param([string]$Root=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..\..')).Path)
$ErrorActionPreference='Stop';$c=Join-Path $Root 'packages/contracts';$rtm=Import-Csv (Join-Path $Root 'planning/sprints/S00/RTM.csv');$cov=Import-Csv (Join-Path $Root 'planning/sprints/S01/remediation/requirements-contract-coverage.csv');$out=[Collections.Generic.List[object]]::new();function Add-Result($id,$ok,$actual){$out.Add([pscustomobject]@{TestID=$id;Result=if($ok){'PASS'}else{'FAIL'};Actual=$actual})}
$raw=Get-Content (Join-Path $c 'openapi/v1.openapi.json') -Raw;$base=$raw|ConvertFrom-Json;function Ops($x){$z=@{};$x.paths.psobject.Properties|%{$p=$_.Name;$_.Value.psobject.Properties|%{$z["$p#$($_.Name)"]=$_.Value}};$z};function Compatible($a,$b){$ao=Ops $a;$bo=Ops $b;foreach($k in $ao.Keys){if(!$bo.ContainsKey($k)){return "removed operation $k"};$ar=$ao[$k].responses.'200'.content.'application/json'.schema.'$ref';$br=$bo[$k].responses.'200'.content.'application/json'.schema.'$ref';if($ar -ne $br){return "changed success response schema $k"};if($ao[$k].'x-authorization-scope' -ne $bo[$k].'x-authorization-scope'){return "changed authorization $k"}};return $null}
$baselineOps=Ops $base;Add-Result 'COVERAGE-01' ($rtm.Count -eq 253 -and $cov.Count -eq 253 -and @($cov.'FR ID'|Select-Object -Unique).Count -eq 253) "RTM=$($rtm.Count), coverage=$($cov.Count), unique=$(@($cov.'FR ID'|Select-Object -Unique).Count)";Add-Result 'OWNER-01' (@($baselineOps.Values|?{!$_.'x-madar-owner-domain' -or !$_.'x-madar-contract-id' -or !$_.'x-madar-srs'}).Count -eq 0) "unowned=$(@($baselineOps.Values|?{!$_.'x-madar-owner-domain' -or !$_.'x-madar-contract-id' -or !$_.'x-madar-srs'}).Count)"
$remove=$raw|ConvertFrom-Json;$first=@($remove.paths.psobject.Properties)[0].Name;$remove.paths.PSObject.Properties.Remove($first);Add-Result 'COMPAT-04' ((Compatible $base $remove) -match 'removed operation') 'Valid candidate with operation removal rejected'
$auth=$raw|ConvertFrom-Json;$k=@((Ops $auth).Keys)[0];$parts=$k-split '#';$auth.paths.($parts[0]).($parts[1]).'x-authorization-scope'='weaker';Add-Result 'COMPAT-05' ((Compatible $base $auth) -match 'changed authorization') 'Valid candidate with authorization change rejected'
$same=$raw|ConvertFrom-Json;$same.info.description='compatible documentation addition';Add-Result 'COMPAT-06' ((Compatible $base $same) -eq $null) 'Compatible candidate accepted';Add-Result 'COMPAT-07' ((Ops ($raw|ConvertFrom-Json)).Count -eq $baselineOps.Count) 'Baseline unchanged after mutations'
$valid=Get-Content (Join-Path $c 'fixtures/valid-booking-confirmed-event.json') -Raw|ConvertFrom-Json;$invalid=Get-Content (Join-Path $c 'fixtures/invalid-event-missing-correlation.json') -Raw|ConvertFrom-Json;Add-Result 'EVENT-01' (![string]::IsNullOrWhiteSpace($valid.correlationId) -and $valid.schemaVersion -eq '1.0.0') 'Valid event metadata present';Add-Result 'EVENT-02' ([string]::IsNullOrWhiteSpace($invalid.correlationId)) 'Missing correlation fixture rejected by envelope rules'
$files=Get-ChildItem $c -Recurse -File;$sensitive=@($files|Select-String -Pattern '(?i)(AKIA[0-9A-Z]{16}|BEGIN (RSA|EC|OPENSSH) PRIVATE KEY|postgres(ql)?://[^\s]+:[^\s]+@|Bearer\s+[A-Za-z0-9._-]{12,}|"otp(Code|Value)"\s*:\s*"[0-9]{4,}" )' -ErrorAction SilentlyContinue);Add-Result 'SEC-02' ($sensitive.Count -eq 0) "secret-pattern matches=$($sensitive.Count)";$safeError='{"code":"VALIDATION_ERROR","message":"Invalid request","correlationId":"c","retryable":false}';$unsafeError='{"code":"INTERNAL","message":"token=synthetic-test-only-123456789","correlationId":"c","retryable":false}';Add-Result 'SEC-03' ($safeError -notmatch '(?i)token=|password=|secret=') 'Safe error accepted';Add-Result 'SEC-04' ($unsafeError -match '(?i)token=') 'Synthetic sensitive error rejected by policy'
$out|Format-Table -AutoSize;if($out.Result -contains 'FAIL'){exit 1}
